// 같은 head 커밋을 두 번 알리지 않는다.
// merge_request 이벤트와 pipeline 이벤트가 같은 커밋을 두고 둘 다 도착할 수 있어서다.
// 키에 커밋 SHA가 들어가므로, MR을 닫지 않고 고쳐서 다시 올리면 키가 달라져 다시 알린다.
//
// 기억은 워크플로 정적 데이터에 6시간. 발행(Publish)된 워크플로에서만 유지되므로
// 수동 실행으로 시험하면 매번 다시 보낸다.
const store = $getWorkflowStaticData('global');
if (store.seenPipelines) delete store.seenPipelines;   // 폴링 시절 키. 한 번만 치운다.
store.seenHeads = store.seenHeads || {};
const now = Date.now();
for (const k of Object.keys(store.seenHeads)) {
  if (now - store.seenHeads[k] > 6 * 60 * 60 * 1000) delete store.seenHeads[k];
}

const out = [];
for (const item of $input.all()) {
  const s = item.json || {};
  if (!s.project || !s.pipeline_id) continue;
  const isMr = s.mr_iid !== null && s.mr_iid !== undefined;
  const key = isMr
    ? `${s.project}!${s.mr_iid}@${s.sha}`
    : `${s.project}@${s.ref}@${s.sha}`;
  if (store.seenHeads[key]) continue;
  store.seenHeads[key] = now;

  out.push({ json: {
    project: s.project, enc: s.enc,
    pipeline_id: s.pipeline_id, ref: s.ref || '', sha: s.sha || '',
    is_mr: isMr, mr_iid: isMr ? s.mr_iid : null,
    trigger: s.event, trigger_action: s.action,
  } });
}
return out;

// MR 파이프라인의 DM 문안. 파이프라인 상세는 「자세히」 노드에서, MR 정보는 이 노드 입력($json)에서 온다.
function esc(s) { return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function dur(sec) {
  if (sec === null || sec === undefined || isNaN(Number(sec))) return '소요 시간 미상';
  const s = Math.round(Number(sec)); const m = Math.floor(s / 60); const r = s % 60;
  return m ? `${m}분 ${String(r).padStart(2, '0')}초` : `${r}초`;
}

const a = $('자세히').item.json || {};
const mr = $json || {};
const m = /^https?:\/\/[^/]+\/(.+?)\/-\/pipelines\/\d+/.exec(a.web_url || '');
const repo = m ? m[1] : '(저장소 미상)';
const who = a.user && a.user.name ? `${esc(a.user.name)}(${esc(a.user.username || '')})` : '(실행자 미상)';
const no = a.iid ?? a.id ?? '';
const pipe = a.web_url ? `<${a.web_url}|파이프라인 #${no}>` : `파이프라인 #${no}`;

const lines = [`*파이프라인 통과* — ${esc(repo)}`];
if (mr.web_url && mr.iid && !mr.error) {
  lines.push(`MR <${mr.web_url}|!${mr.iid}> ${esc(mr.title)}`);
  lines.push(`${esc(mr.source_branch)} → ${esc(mr.target_branch)} · ${who}`);
} else {
  const iid = $('새 것 고르기').item.json.mr_iid;
  lines.push(`MR !${iid || '?'} (MR 정보를 못 읽음) · ${who}`);
}
lines.push(`${dur(a.duration)} · ${pipe}`);

return { json: { text: lines.join('\n'), repo, pipeline_id: a.id, pipeline_url: a.web_url, mr_iid: mr.iid || null, mr_url: mr.web_url || null } };

// MR이 아닌 파이프라인(main 병합 뒤 · 태그)의 DM 문안. 입력($json)은 파이프라인 상세.
function esc(s) { return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function dur(sec) {
  if (sec === null || sec === undefined || isNaN(Number(sec))) return '소요 시간 미상';
  const s = Math.round(Number(sec)); const m = Math.floor(s / 60); const r = s % 60;
  return m ? `${m}분 ${String(r).padStart(2, '0')}초` : `${r}초`;
}

const a = $json || {};
const m = /^https?:\/\/[^/]+\/(.+?)\/-\/pipelines\/\d+/.exec(a.web_url || '');
const repo = m ? m[1] : '(저장소 미상)';
const who = a.user && a.user.name ? `${esc(a.user.name)}(${esc(a.user.username || '')})` : '(실행자 미상)';
const no = a.iid ?? a.id ?? '';
const pipe = a.web_url ? `<${a.web_url}|파이프라인 #${no}>` : `파이프라인 #${no}`;
// 세 저장소의 기본 브랜치는 전부 main(.gitlab-ci.yml 실독, 2026-09-02).
const where = a.tag
  ? `태그 \`${esc(a.ref)}\` (릴리스 파이프라인)`
  : a.ref === 'main'
    ? `기본 브랜치 \`${esc(a.ref)}\` (병합 뒤 파이프라인)`
    : `브랜치 \`${esc(a.ref)}\``;

const lines = [`*파이프라인 통과* — ${esc(repo)}`, `${where} · ${who}`, `${dur(a.duration)} · ${pipe}`];
return { json: { text: lines.join('\n'), repo, pipeline_id: a.id, pipeline_url: a.web_url, ref: a.ref } };

// 조건부 봇 승인 판정 — 객관적으로 확인 가능한 것만 본다.
// 하나라도 걸리면 자동승인하지 않고 사람에게 넘긴다.
const DEP = [
  /(^|\/)(package\.json|package-lock\.json|npm-shrinkwrap\.json|yarn\.lock|pnpm-lock\.yaml)$/i,
  /(^|\/)(pyproject\.toml|uv\.lock|poetry\.lock|Pipfile(\.lock)?|setup\.(cfg|py)|requirements[^\/]*\.txt)$/i,
  /(^|\/)(build\.gradle(\.kts)?|settings\.gradle(\.kts)?|gradle\.properties|libs\.versions\.toml|gradle-wrapper\.properties)$/i,
  /(^|\/)Dockerfile[^\/]*$/i,
  /(^|\/)docker-compose[^\/]*\.ya?ml$/i,
  /(^|\/)\.gitlab-ci\.yml$/i,
  /(^|\/)\.trivyignore$/i,
  /(^|\/)\.nvmrc$/i,
  /(^|\/)\.pre-commit-config\.ya?ml$/i,
  /(^|\/)(ci|docker|gradle)\//i
];

const src  = $('새 것 고르기').item.json || {};
const mr   = $('MR 정보').item.json || {};
const base = $('문안(MR)').item.json || {};
const changes = ($json && Array.isArray($json.changes)) ? $json.changes : [];

const paths = [];
for (const c of changes) {
  if (c.new_path) paths.push(c.new_path);
  if (c.old_path && c.old_path !== c.new_path) paths.push(c.old_path);
}
const hits = [...new Set(paths.filter(p => DEP.some(re => re.test(p))))];

const blockers = [];
if (hits.length) blockers.push('의존성·빌드·CI 파일 변경 (' + hits.join(', ') + ')');
if (mr.draft === true || /^\s*(draft|wip)\s*:/i.test(String(mr.title || ''))) blockers.push('초안(Draft) 상태');
if (mr.has_conflicts === true) blockers.push('병합 충돌 있음');
if (mr.blocking_discussions_resolved === false) blockers.push('미해결 토론 있음');
if (mr.state && mr.state !== 'opened') blockers.push('열린 MR이 아님 (' + mr.state + ')');
if (!changes.length) blockers.push('변경 파일 목록을 읽지 못함');

const auto_ok = blockers.length === 0;

const checked = [
  '파이프라인 통과',
  '의존성·빌드·CI 파일 무변경 (' + paths.length + '개 파일 확인)',
  '초안 아님',
  '병합 충돌 없음',
  '미해결 토론 없음'
];

const approve_comment =
  '[봇 자동승인 — 조건부]\n\n' +
  '이 승인은 사람의 보안 검토가 아닙니다. 아래 객관적 조건을 자동으로 확인한 결과입니다.\n' +
  checked.map(function (c) { return '· ' + c; }).join('\n') + '\n\n' +
  '의존성·빌드·CI 파일이 바뀌었거나 위 조건 중 하나라도 걸리면 자동승인하지 않고 사람에게 넘깁니다.\n' +
  '외부 라이브러리(SOUP) 취약점 판정이 필요한 변경은 이 경로로 승인되지 않습니다.';

const line = auto_ok
  ? '\n\n[조건 충족 — 봇 자동승인 대상]\n· 확인: ' + checked.join(' / ')
  : '\n\n[사람 확인 필요]\n· 걸린 것: ' + blockers.join(' / ');

return { json: Object.assign({}, base, {
  text: String(base.text || '') + line,
  auto_ok: auto_ok,
  blockers: blockers,
  checked_conditions: checked,
  approve_comment: approve_comment,
  changed_paths: paths,
  dep_hits: hits,
  enc: src.enc,
  mr_iid: src.mr_iid,
  project: src.project
}) };

// GitLab 웹훅 한 건을 해석한다. 이 워크플로가 다루는 것만 남기고 나머지는 버린다.
//
// 두 종류를 같은 웹훅으로 받는다:
//   merge_request — MR이 올라옴(open) · 다시 열림(reopen) · 닫지 않은 MR에 새 커밋 push(update+oldrev)
//   pipeline      — 파이프라인이 끝남 (success만 통과시킨다)
//
// 둘 다 받는 이유: MR을 여는 순간에는 파이프라인이 아직 안 끝나 있고,
// 파이프라인이 끝나는 순간에는 그것이 방금 올라온 MR인지 알 길이 없다.
// merge_request 이벤트는 "이미 통과해 있으면 바로", pipeline 이벤트는 "이제 막 통과했으면"을 맡는다.
// 어느 쪽이 먼저 와도 알림은 한 번이다 — 중복은 「새 것 고르기」가 head 커밋 기준으로 걸러낸다.
const raw = $input.first().json || {};
const b = raw.body && typeof raw.body === 'object' ? raw.body : raw;   // Webhook 노드는 payload를 body에 담는다
const oa = b.object_attributes || {};
const kind = b.object_kind || b.event_type || '';
const project = (b.project && b.project.path_with_namespace) || '';
if (!project) return [];

if (kind === 'merge_request') {
  const action = String(oa.action || '');
  const pushedNewCommits = action === 'update' && !!(oa.oldrev || b.oldrev);  // 닫지 않은 채 변경 후 재요청
  if (!['open', 'reopen'].includes(action) && !pushedNewCommits) return [];
  if (oa.state && oa.state !== 'opened') return [];
  const sha = (oa.last_commit && oa.last_commit.id) || oa.last_commit_id || '';
  if (!oa.iid || !sha) return [];
  return [{ json: {
    event: 'merge_request', action,
    project, enc: encodeURIComponent(project),
    mr_iid: Number(oa.iid), sha,
    is_mr_event: true,
  } }];
}

if (kind === 'pipeline') {
  if (oa.status !== 'success' || !oa.id) return [];
  const fromRef = (/^refs\/merge-requests\/(\d+)\//.exec(String(oa.ref || '')) || [])[1];
  const mrIid = (b.merge_request && b.merge_request.iid) || fromRef || null;
  return [{ json: {
    event: 'pipeline', action: String(oa.status),
    project, enc: encodeURIComponent(project),
    pipeline_id: oa.id, ref: oa.ref || '', sha: oa.sha || '',
    mr_iid: mrIid === null ? null : Number(mrIid),
    is_mr_event: false,
  } }];
}

return [];

// merge_request 이벤트로 들어온 건: 그 MR의 head 커밋 파이프라인이 '이미 통과해 있는지'만 본다.
// 아직 안 끝났으면 여기서 조용히 끝낸다 — 끝나는 순간 pipeline 웹훅이 이 워크플로를 다시 깨운다.
// 그래서 여기서 기다리거나 되풀이 조회할 필요가 없다.
const src = $('이벤트 해석').first().json || {};
const rows = $input.all().map((i) => i.json).filter((p) => p && p.id && !p.error);
const hit = rows.find((p) => p.sha === src.sha && p.status === 'success');
if (!hit) return [];
return [{ json: Object.assign({}, src, {
  pipeline_id: hit.id,
  ref: hit.ref || '',
  sha: hit.sha || src.sha,
}) }];
